function combinationSum(candidates, target) {
  const answers = [];
  const current = [];

  function solve(start, remaining) {
    if (remaining === 0) {
      answers.push([...current]);
      return;
    }

    for (let i = start; i < candidates.length; i++) {
      if (candidates[i] > remaining) continue;   // the prune

      current.push(candidates[i]);
      solve(i, remaining - candidates[i]);       // i, not i+1: reuse allowed
      current.pop();
    }
  }

  solve(0, target);
  return answers;
}

